//! Deterministic navigation history and URL resolution.
#[derive(Default,Debug)] pub struct Navigation { pub current:Option<String>, pub history:Vec<String>, pub position:usize }
impl Navigation { pub fn navigate(&mut self,url:impl Into<String>){let u=url.into();if self.position+1<self.history.len(){self.history.truncate(self.position+1)} self.history.push(u.clone());self.position=self.history.len()-1;self.current=Some(u)} pub fn back(&mut self)->Option<&str>{if self.position>0{self.position-=1;self.current=Some(self.history[self.position].clone())} self.current.as_deref()} pub fn forward(&mut self)->Option<&str>{if self.position+1<self.history.len(){self.position+=1;self.current=Some(self.history[self.position].clone())} self.current.as_deref()} pub fn reload(&self)->Option<&str>{self.current.as_deref()} pub fn stop(&mut self){} }
